<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Plus,Search,Settings2} from 'lucide-vue-next'
import Panel from '../components/Panel.vue'
import Modal from '../components/Modal.vue'
import TelemetryChart from '../components/TelemetryChart.vue'
import {useWorkspace} from '../stores/workspace'
import {metricInfo} from '../domain'
import type {Metric,Segment} from '../domain'
import {samplesFor} from '../services/demo'
import {csv,time} from '../utils'
const store=useWorkspace(),route=useRoute(),router=useRouter(),ent=ref(store.context?.enterprise.id??''),net=ref(store.context?.network.id??''),seg=ref(store.context?.segment.id??''),search=ref(''),param=ref<Metric|'all'>('all'),start=ref('2026-11-03T00:00'),end=ref('2026-11-03T08:00'),page=ref(1),maintain=ref(false),editKind=ref('segment'),editId=ref(''),editName=ref(''),editCode=ref(''),diameter=ref(300),length=ref(840),active=ref(true),error=ref('')
const nets=computed(()=>store.state.networks.filter(n=>n.enterpriseId===ent.value)),segs=computed(()=>store.state.segments.filter(s=>s.networkId===net.value&&(!search.value||(s.name+s.code).includes(search.value)))),c=computed(()=>store.contextFor(seg.value)),rows=computed(()=>c.value?samplesFor(c.value,start.value,end.value).filter(s=>param.value==='all'||s.metric===param.value):[]),visible=computed(()=>rows.value.slice((page.value-1)*5,page.value*5)),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/5)))
watch(ent,()=>{net.value='';seg.value=''});watch(net,()=>{seg.value=''});watch([param,start,end,seg],()=>page.value=1)
function apply(){if(!c.value)return;if(!c.value.segment.active||!c.value.network.active||!c.value.enterprise.active){store.notify('该对象已停用，不能选为当前分析对象。');return}store.select(seg.value);store.notify('当前管段已切换，所有业务入口同步更新。');router.replace('/networks')}
function create(){if(!c.value)return;store.select(seg.value);router.push({path:'/detections',query:{create:'1',start:start.value,end:end.value,metric:param.value}})}
function exportCsv(){if(!rows.value.length){store.notify('当前范围无数据可导出。');return}csv([['采集时间','测点','参数','数值','单位','质量'],...rows.value.map(r=>[time(r.time),r.point,metricInfo[r.metric].label,r.value,r.unit,r.quality])],`${c.value?.segment.code}-运行数据.csv`)}
function openEdit(id=''){editId.value=id;const item=editKind.value==='enterprise'?store.state.enterprises.find(x=>x.id===id):editKind.value==='network'?store.state.networks.find(x=>x.id===id):store.state.segments.find(x=>x.id===id);editName.value=item?.name??'';editCode.value=item?.code??'';active.value=item?.active??true;if(item&&'diameter'in item){diameter.value=(item as Segment).diameter;length.value=(item as Segment).length}error.value='';maintain.value=true}
function save(){error.value='';if(!editName.value.trim()||!editCode.value.trim()){error.value='名称和编号为必填项。';return}const list=editKind.value==='enterprise'?store.state.enterprises:editKind.value==='network'?store.state.networks:store.state.segments;if(list.some(x=>x.id!==editId.value&&x.code===editCode.value)){error.value='编号已存在，请使用唯一编号。';return}if(editKind.value!=='enterprise'&&!ent.value||editKind.value==='segment'&&!net.value){error.value='请先选择对应企业和管网。';return}if(editKind.value==='segment'&&(!(diameter.value>0)||!(length.value>0))){error.value='管径和长度须为正数。';return}const existing=list.find(x=>x.id===editId.value);const basic={name:editName.value.trim(),code:editCode.value.trim(),active:active.value};if(existing){Object.assign(existing,basic);if('diameter'in existing)Object.assign(existing,{diameter:diameter.value,length:length.value})}else{const id=`${editKind.value}-${Date.now()}`;if(editKind.value==='enterprise')store.state.enterprises.push({id,...basic});else if(editKind.value==='network')store.state.networks.push({id,enterpriseId:ent.value,...basic});else store.state.segments.push({id,networkId:net.value,...basic,diameter:diameter.value,length:length.value,kind:'secondary',metrics:[],hasData:false})}store.save();maintain.value=false;store.notify(store.storageError?'已在本次会话更新，请检查本地保存提示。':'组织信息已保存；历史任务保留原对象快照。')}
</script>
<template><div class="page-stack">
<Panel title="企业 / 供热管网 / 管段选择"><template #tools><span class="badge orange" v-if="route.query.pick">请选择需要切换的管段</span><select v-model="editKind" aria-label="维护对象类型"><option value="enterprise">企业</option><option value="network">供热管网</option><option value="segment">管段</option></select><button class="secondary" @click="openEdit()"><Plus :size="15" />新增</button><button class="icon-button" aria-label="编辑当前组织信息" @click="openEdit(editKind==='enterprise'?ent:editKind==='network'?net:seg)"><Settings2 :size="16" /></button></template>
<div class="hierarchy"><label><span>所属企业（Tier 1）</span><select v-model="ent" aria-label="企业选择"><option value="">请选择企业</option><option v-for="e in store.state.enterprises" :key="e.id" :value="e.id">{{e.name}}{{!e.active?'（已停用）':''}}</option></select><small>{{store.state.networks.filter(n=>n.enterpriseId===ent).length}} 个供热管网</small></label><label><span>供热管网（Tier 2）</span><select v-model="net" :disabled="!ent" aria-label="供热管网选择"><option value="">请选择供热管网</option><option v-for="n in nets" :key="n.id" :value="n.id">{{n.name}}{{!n.active?'（已停用）':''}}</option></select><small v-if="ent&&!nets.length">当前企业下暂无供热管网</small><small v-else>{{store.state.segments.filter(s=>s.networkId===net).length}} 个管段</small></label><label class="target-object"><span>目标管段（Tier 3）</span><select v-model="seg" :disabled="!net" aria-label="管段选择"><option value="">请选择管段</option><option v-for="s in segs" :key="s.id" :value="s.id">{{s.name}} · {{s.code}}{{!s.active?'（已停用）':''}}</option></select><small v-if="net&&!segs.length">暂无匹配管段</small><small v-else>{{c?.segment.code??'选择后查看详情'}} · {{seg===store.state.selectedId?'已选择':'待确认'}}</small></label><div class="picker-actions"><label class="search-box"><Search :size="15"/><input v-model="search" placeholder="搜索管段名称或编号" aria-label="搜索管段" /></label><button class="primary" :disabled="!c" @click="apply">确认选择</button></div></div></Panel>
<template v-if="c"><div class="grid metrics-four"><div v-for="m in c.segment.metrics" :key="m" class="metric-card" :style="{'--metric':metricInfo[m].color}"><div class="flex between"><strong>{{metricInfo[m].label}}</strong><span :class="['badge',m==='return'?'amber':'green']">{{c.segment.hasData?'示例采样':'无数据'}}</span></div><div class="metric-value" :style="{color:'var(--metric-'+m+'-text)'}">{{c.segment.hasData?(m==='supply'?(c.segment.kind==='primary'?109.8:68.4):m==='return'?42.1:m==='pressure'?.5:186.5):'—'}}<small>{{metricInfo[m].unit}}</small></div><svg class="spark" viewBox="0 0 240 36" preserveAspectRatio="none" aria-hidden="true"><path d="M0 24 Q40 8 80 20 T160 22 T240 15" fill="none" :stroke="metricInfo[m].color" stroke-width="2" /></svg><p class="muted">测点：{{metricInfo[m].point}} · {{c.segment.hasData?'演示数据':'等待数据'}}</p></div></div><div v-if="!c.segment.metrics.length" class="empty">当前管段未配置监测参数，暂不能发起检测。</div>
<div class="grid two-one"><Panel title="高精时序遥测趋势与异常区间"><template #tools><div class="segmented"><button v-for="m in (['all',...c.segment.metrics] as const)" :key="m" :class="{selected:param===m}" @click="param=m">{{m==='all'?'综合':metricInfo[m].label}}</button></div></template><TelemetryChart :key="seg+String(c.segment.hasData)" :context="c" :metrics="param==='all'?c.segment.metrics:[param]" :start="start" :end="end"/><p class="chart-caption">演示时间范围：2026-11-03 · 不同参数使用独立单位坐标</p></Panel><Panel title="管段基本信息与分析入口"><dl class="detail-list"><div><dt>管段名称</dt><dd>{{c.segment.name}}</dd></div><div><dt>管段编号</dt><dd>{{c.segment.code}}</dd></div><div><dt>所属企业</dt><dd>{{c.enterprise.name}}</dd></div><div><dt>所属管网</dt><dd>{{c.network.name}}</dd></div><div><dt>管径 / 长度</dt><dd>DN{{c.segment.diameter}} / {{c.segment.length}} m</dd></div><div><dt>管网属性</dt><dd>{{c.segment.kind==='primary'?'一次网':'二次网'}}</dd></div><div><dt>对象状态</dt><dd>{{c.segment.active?'启用':'停用'}}</dd></div></dl><div class="inset"><h3 class="orange">AI诊断辅助入口</h3><p class="muted">先完成本管段异常检测，再根据结果分析参数关联、可能原因和核查方向。</p></div><button class="wide primary mt" :disabled="!c.segment.hasData||!c.segment.metrics.length||!c.segment.active" @click="create">发起异常检测</button></Panel></div>
<Panel title="运行历史数据列表"><template #tools><button class="secondary" :disabled="!rows.length" @click="exportCsv">导出 CSV</button><button class="primary" :disabled="!rows.length||!c.segment.active" @click="create">发起异常检测</button></template><form class="filter-bar" @submit.prevent="page=1"><label>开始时间<input v-model="start" type="datetime-local" /></label><label>结束时间<input v-model="end" type="datetime-local" /></label><label>监测参数<select v-model="param"><option value="all">全部参数</option><option v-for="m in c.segment.metrics" :key="m" :value="m">{{metricInfo[m].label}}</option></select></label></form><p v-if="new Date(start)>=new Date(end)" class="error" role="alert">起始时间必须早于结束时间。</p><div class="table-wrap"><table><thead><tr><th>采样时间</th><th>测点编号与参数</th><th>采集数值</th><th>工程单位</th><th>数据质量</th><th>操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.time+r.metric"><td class="mono">{{time(r.time)}}</td><td>{{r.point}} · {{metricInfo[r.metric].label}}</td><td :style="{color:'var(--metric-'+r.metric+'-text)'}">{{r.value}}</td><td>{{r.unit}}</td><td><span class="badge green">{{r.quality}}</span></td><td><button class="text-button" @click="param=r.metric">查看参数趋势</button></td></tr><tr v-if="!visible.length"><td class="empty" colspan="6">当前范围暂无运行数据，请调整条件或切换管段。</td></tr></tbody></table></div><div class="pagination"><span>共 {{rows.length}} 条 · 第 {{page}} / {{pages}} 页</span><button :disabled="page===1" @click="page--">上一页</button><button :disabled="page>=pages" @click="page++">下一页</button></div></Panel></template><div v-else class="empty">请选择企业、供热管网和管段，查看对应运行数据。</div>
<Modal v-if="maintain" :title="(editId?'编辑':'新增')+(editKind==='enterprise'?'企业':editKind==='network'?'供热管网':'管段')" @close="maintain=false"><form class="form-stack" @submit.prevent="save"><label>名称 *<input v-model="editName" maxlength="60" required /></label><label>编号 *<input v-model="editCode" maxlength="30" required /></label><template v-if="editKind==='segment'"><label>管径（mm）*<input v-model.number="diameter" type="number" min="1" required /></label><label>长度（m）*<input v-model.number="length" type="number" min="1" required /></label><p class="muted">新管段默认无参数和运行数据，数据接入方案另行确定。</p></template><label class="check-label"><input v-model="active" type="checkbox"/>启用对象</label><p class="muted">停用后不允许创建新任务，历史记录继续保留。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary">保存信息</button></form></Modal>
</div></template>

